package server_test

import (
	"os"
	"path/filepath"
	"testing"

	apiv1 "github.com/uw-syfi/vibesys/gateway/gen/vibesys/api/v1"
	storev1 "github.com/uw-syfi/vibesys/gateway/gen/vibesys/store/v1"
	"google.golang.org/protobuf/proto"
)

// These files are generated by the Python FileRunLogWriter, rather than a Go
// imitation of the writer's framing, publication order or checkpoint offsets.
func TestPythonWriterSkeletonFixtures(t *testing.T) {
	for _, name := range []string{"core", "epochs"} {
		t.Run(name, func(t *testing.T) {
			f := start(t)
			source := filepath.Join("../../../proto/testdata/skeleton", name)
			for _, filename := range []string{"run.log", "run.head"} {
				payload, err := os.ReadFile(filepath.Join(source, filename))
				if err != nil {
					t.Fatal(err)
				}
				write(t, filepath.Join(f.run, filename), false, payload)
			}
			entries, err := os.ReadDir(filepath.Join(source, "keyframes"))
			if err != nil {
				t.Fatal(err)
			}
			if err := os.Mkdir(filepath.Join(f.run, "keyframes"), 0700); err != nil {
				t.Fatal(err)
			}
			for _, entry := range entries {
				payload, err := os.ReadFile(filepath.Join(source, "keyframes", entry.Name()))
				if err != nil {
					t.Fatal(err)
				}
				write(t, filepath.Join(f.run, "keyframes", entry.Name()), false, payload)
			}
			expected, err := os.ReadFile(filepath.Join(source, "expected.pb"))
			if err != nil {
				t.Fatal(err)
			}
			var keyframe storev1.Keyframe
			if err := proto.Unmarshal(expected, &keyframe); err != nil {
				t.Fatal(err)
			}
			got, err := client(t, f, false).Skeleton(f.ctx, &apiv1.SkeletonRequest{RunId: "run-1"})
			if err != nil {
				t.Fatal(err)
			}
			var actual storev1.Keyframe
			if err := proto.Unmarshal(got.Keyframe, &actual); err != nil {
				t.Fatal(err)
			}
			if !proto.Equal(&actual, &keyframe) || got.CommittedSeq != keyframe.ThroughSeq || !got.Complete || len(got.Records) != 0 {
				t.Fatalf("Python checkpoint did not round trip: %v", got)
			}

		})
	}
}
